insert into public.questions(id,content) values ('demo-001','{"id":"demo-001","number":1,"examType":"実技","field":"渦度・渦度移流","theme":"渦度・渦度移流","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"500hPa天気図で正渦度移流を判断するには？","answer":"風によって、その地点より大きな渦度が運ばれてくるかを確認する。","explanation":{"where":"500hPaの風と渦度分布を見る。","read":"風上と現在地の渦度を比べる。","judge":"風上の渦度が大きければ正渦度移流と判断する。","caution":"渦度の値が正であることと、正渦度移流は別の概念。"},"memorize":"正渦度移流は風による渦度の増加。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-002','{"id":"demo-002","number":2,"examType":"実技","field":"温度移流","theme":"温度移流","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"暖気移流はどのように判断するか？","answer":"風上から、その地点より暖かい空気が運ばれてくる場合に暖気移流となる。","explanation":{"where":"風向と等温線を見る。","read":"風上側と現在地の温度を比べる。","judge":"高温側から低温側へ風が等温線を横切れば暖気移流。","caution":"気温の上昇には日射など別の原因もある。"},"memorize":"暖気移流は風によって暖気が入ること。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-003','{"id":"demo-003","number":3,"examType":"実技","field":"500hPa","theme":"500hPa","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"500hPa天気図のトラフとは？","answer":"等高度線が低緯度側へ張り出す、気圧の谷に相当する部分。","explanation":{"where":"等高度線の形を見る。","read":"低緯度側への曲がりを追う。","judge":"谷の軸を読み取る。","caution":"等高度線の曲がりだけで地上の降水を断定しない。"},"memorize":"トラフは上空の気圧の谷。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-004','{"id":"demo-004","number":4,"examType":"実技","field":"850hPa","theme":"850hPa","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"850hPa天気図で主に確認するものは？","answer":"下層の温度分布、風、湿りなど。","explanation":{"where":"気温・風・湿りの分布を見る。","read":"暖湿気の流入経路を探す。","judge":"前線や降水域との関係を検討する。","caution":"山岳では850hPa面が地面の下になる場合がある。"},"memorize":"850hPaで下層の空気の性質を確認。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-005','{"id":"demo-005","number":5,"examType":"実技","field":"700hPa","theme":"700hPa","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"700hPaの湿潤域だけで降水を断定できるか？","answer":"断定できない。上昇流や他の高度の湿りなども確認する。","explanation":{"where":"湿りと鉛直流を見る。","read":"湿潤域と上昇流域の重なりを調べる。","judge":"複数の情報から降水の可能性を判断する。","caution":"湿潤でも必ず地上で降水になるとは限らない。"},"memorize":"湿りと持ち上げる仕組みを合わせて見る。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-006','{"id":"demo-006","number":6,"examType":"実技","field":"300hPa","theme":"300hPa","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"300hPa天気図でジェット気流を探すには？","answer":"強風域の分布と、その軸を確認する。","explanation":{"where":"風速の分布を見る。","read":"周囲より風速が大きい帯状域を追う。","judge":"強風軸の位置を読む。","caution":"ジェット気流の高度は一定ではない。"},"memorize":"上層の強風帯からジェットの位置を読む。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-007','{"id":"demo-007","number":7,"examType":"実技","field":"地上天気図","theme":"地上天気図","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"等圧線の間隔が狭いと何が大きいか？","answer":"水平気圧傾度が大きい。","explanation":{"where":"同じ等圧線間隔の地上天気図を見る。","read":"等圧線の込み合う場所を探す。","judge":"距離あたりの気圧差が大きいと判断する。","caution":"地上風は摩擦や地形にも影響される。"},"memorize":"等圧線が密な場所は気圧傾度が大きい。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-008','{"id":"demo-008","number":8,"examType":"実技","field":"前線解析","theme":"前線解析","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"寒冷前線とはどのような境界か？","answer":"寒気が暖気側へ進む前線。","explanation":{"where":"気温・風向・前線の移動を見る。","read":"寒気の進行方向を確認する。","judge":"寒気が暖気を押し上げる境界と判断する。","caution":"降水域の幅や強さは状況によって異なる。"},"memorize":"寒冷前線では寒気が前進。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-009','{"id":"demo-009","number":9,"examType":"実技","field":"前線解析","theme":"前線解析","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"温暖前線とはどのような境界か？","answer":"暖気が寒気側へ進む前線。","explanation":{"where":"気温分布と前線の移動を見る。","read":"暖気が進む方向を確認する。","judge":"暖気が寒気の上を上昇する構造を考える。","caution":"雲や雨の分布は毎回同じではない。"},"memorize":"温暖前線では暖気が前進。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-010','{"id":"demo-010","number":10,"examType":"実技","field":"温帯低気圧","theme":"温帯低気圧","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"温帯低気圧の主要な発達のエネルギー源は？","answer":"南北の温度差に対応する有効位置エネルギー。","explanation":{"where":"温度分布と低気圧の構造を見る。","read":"寒気と暖気の配置を確認する。","judge":"傾圧性との関係を考える。","caution":"潜熱の放出も発達に寄与する。"},"memorize":"温帯低気圧は温度差を利用して発達。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-011','{"id":"demo-011","number":11,"examType":"実技","field":"台風","theme":"台風","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"台風の主要なエネルギー源は？","answer":"暖かい海から供給された水蒸気が凝結するときに放出する潜熱。","explanation":{"where":"海面と対流雲を見る。","read":"水蒸気供給と積乱雲の発達を確認する。","judge":"凝結による加熱が循環を維持すると考える。","caution":"暖かい海だけで必ず発達するわけではない。"},"memorize":"台風のエネルギー源は凝結に伴う潜熱。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-012','{"id":"demo-012","number":12,"examType":"実技","field":"上昇流・下降流","theme":"上昇流・下降流","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"気圧座標の鉛直速度ωが負のとき、空気は上昇か下降か？","answer":"上昇。","explanation":{"where":"鉛直速度の定義と単位を見る。","read":"ωは空気塊に沿った気圧の時間変化。","judge":"上昇すると気圧が下がるため負になる。","caution":"高度座標の鉛直速度とは符号が異なる。"},"memorize":"ωが負なら上昇、正なら下降。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-013','{"id":"demo-013","number":13,"examType":"学科一般","field":"大気の安定度","theme":"大気の安定度","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"未飽和の空気塊が断熱的に上昇すると温度はどうなるか？","answer":"周囲の気圧が低くなるため膨張し、温度が下がる。","explanation":{"where":"空気塊の高度変化を見る。","read":"上昇による気圧低下を考える。","judge":"膨張に伴う冷却と判断する。","caution":"飽和後は凝結による潜熱放出を考慮する。"},"memorize":"上昇する空気は膨張して冷える。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-014','{"id":"demo-014","number":14,"examType":"学科一般","field":"大気の安定度","theme":"大気の安定度","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"相対湿度とは何か？","answer":"その温度での飽和水蒸気圧に対する、実際の水蒸気圧の比を百分率で表したもの。","explanation":{"where":"気温と水蒸気圧を見る。","read":"現在の水蒸気圧と飽和値を比べる。","judge":"比に100を掛ける。","caution":"水蒸気量が同じでも気温で相対湿度は変わる。"},"memorize":"相対湿度は飽和に対する割合。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-015','{"id":"demo-015","number":15,"examType":"実技","field":"気象衛星画像","theme":"気象衛星画像","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"赤外画像で雲頂の高さを考える際の基本は？","answer":"一般に雲頂温度が低いほど、雲頂が高いと考える。","explanation":{"where":"赤外画像の温度と凡例を見る。","read":"低温の雲域を探す。","judge":"気温の鉛直分布も踏まえて高さを考える。","caution":"逆転層や薄い雲などでは単純に判断できない。"},"memorize":"赤外画像では雲頂温度を見る。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-016','{"id":"demo-016","number":16,"examType":"実技","field":"気象衛星画像","theme":"気象衛星画像","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"可視画像を夜間の雲の判別に利用しにくいのはなぜ？","answer":"可視画像は太陽光の反射を観測するため。","explanation":{"where":"観測波長と昼夜を確認する。","read":"照明となる太陽光の有無を考える。","judge":"夜間は通常の可視画像で雲を捉えにくい。","caution":"夜間は赤外画像などを利用する。"},"memorize":"可視画像は反射した太陽光。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-017','{"id":"demo-017","number":17,"examType":"学科一般","field":"数値予報","theme":"数値予報","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"数値予報の初期値とは？","answer":"予報計算の出発時刻における、大気の状態を表す値。","explanation":{"where":"解析時刻と予報対象時刻を見る。","read":"計算の出発点を確認する。","judge":"観測とデータ同化に基づく状態と理解する。","caution":"観測のない地点も解析により値が与えられる。"},"memorize":"初期値は予報計算の出発点。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-018','{"id":"demo-018","number":18,"examType":"学科一般","field":"数値予報","theme":"数値予報","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"アンサンブル予報を利用する目的は？","answer":"複数の予測から、予報の不確実性を評価するため。","explanation":{"where":"複数の予報結果を見る。","read":"結果のばらつきを確認する。","judge":"一致度や発生確率の情報を判断に使う。","caution":"平均値だけでは極端な現象を捉えにくい場合がある。"},"memorize":"アンサンブルは予報の幅を見る。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-019','{"id":"demo-019","number":19,"examType":"学科一般","field":"その他","theme":"その他","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"北半球でコリオリの力は運動方向のどちらに働くか？","answer":"運動方向の右向き。","explanation":{"where":"半球と運動方向を確認する。","read":"進行方向を基準に左右を考える。","judge":"北半球なら右向きに働く。","caution":"南半球では左向き、赤道上ではゼロ。"},"memorize":"北半球では進行方向の右。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
insert into public.questions(id,content) values ('demo-020','{"id":"demo-020","number":20,"examType":"実技","field":"地上天気図","theme":"地上天気図","kind":"オリジナル","examSession":null,"practicalPart":null,"questionNumber":null,"question":"北半球の地上低気圧の周りの風の基本的な向きは？","answer":"反時計回りに、中心へ吹き込む。","explanation":{"where":"低気圧中心と風向を見る。","read":"回転方向と中心への成分を確認する。","judge":"摩擦を受ける地上風の特徴と判断する。","caution":"実際の風は地形などで変化する。"},"memorize":"地上低気圧では反時計回りに吹き込む。","sourceName":"試作版サンプル問題 v1","source":"画面確認用に作成したオリジナル問題（公式過去問ではありません）","reviewStatus":"sample","images":[]}'::jsonb) on conflict(id) do nothing;
